#!/bin/bash
# Run switch-core 0.31.0 on the host (upstream's own `just run` topology).
# Env comes from this dir's .env (generated by upstream's script); DB is the
# host PostgreSQL on localhost:5432.
set -euo pipefail
cd "$(dirname "$0")"
set -a; . ./.env; set +a
# Sanitize: this environment's NO_PROXY carries bracketed IPv6 entries that crash httpx URL parsing.
export NO_PROXY=localhost,127.0.0.1
export no_proxy=localhost,127.0.0.1
export DB_HOST=localhost
export GATEWAY_COOKIE_SECURE=false
export FEATURE_FLAGS_ENABLED=agent_management,group_chats,agent_chats,follow_the_conversation,service_connections
export MATRIX_SERVER_NAME=localhost
cd ${SWITCH_CHECKOUT:-$HOME/switch}
exec core/.venv/bin/python -m switch_core.main
